    $$["/images/destinations/hampi/hero.jpg","/images/destinations/hampi/stone-chariot.jpg","/images/destinations/hampi/virupaksha-temple.jpg","/images/destinations/hampi/tungabhadra-river.jpg"]$$::jsonb,
