    $$["/images/destinations/sikkim-darjeeling/hero.jpg","/images/destinations/sikkim-darjeeling/glenburn-tea-estate.jpg","/images/destinations/sikkim-darjeeling/kanchenjunga-dawn.jpg","/images/destinations/sikkim-darjeeling/rumtek-monastery.jpg"]$$::jsonb,
